def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.abs(remaining - 0.5))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = 0.1 * bins
    score = -np.exp(np.abs(remaining - target) / (bins + 1e-8))
    return np.where((bins < item) | (bins <= 0), -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_fill = 0.85
    remaining = bins - item
    post_fill = 1.0 - (remaining / bins)
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.square(post_fill - target_fill))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_remaining = 0.2 * bins
    score = -((remaining - optimal_remaining) ** 2) / (bins + 1e-8)
    return np.where((bins < item) | (bins <= 0), -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = remaining / (bins + 1e-8)
    score = -np.exp(np.abs(ratio - 0.2))
    return np.where((bins < item) | (bins <= 0), -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = 1.0 - (remaining / bins)
    return np.where((bins < item) | (bins <= 0), -np.inf, np.where(utilization > 0.9, -np.inf, utilization))
